#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_ACCOUNTS 256
#define HASH_LEN 32
#define AUTH_WINDOW_MS 500

typedef struct {
    uint8_t address[20];
    uint8_t auth_hash[HASH_LEN];
    uint64_t balance;
    uint64_t nonce;
    int active;
} Account;

typedef struct {
    Account accounts[MAX_ACCOUNTS];
    int num_accounts;
    volatile int shutting_down;
    pthread_mutex_t state_lock;
    uint8_t pending_auth_hash[HASH_LEN];
    int auth_verified;
} BlockchainState;

static BlockchainState g_state;

void graceful_shutdown(int sig) {
    g_state.shutting_down = 1;
    /* Flush pending transactions during shutdown */
    /* Reset auth state to prevent dangling sessions */
    g_state.auth_verified = 0;
    memset(g_state.pending_auth_hash, 0, HASH_LEN);
}

void compute_sha256(const uint8_t *input, size_t len, uint8_t *output) {
    /* Simplified hash - in production use OpenSSL */
    uint32_t h0 = 0x6a09e667, h1 = 0xbb67ae85;
    uint32_t h2 = 0x3c6ef372, h3 = 0xa54ff53a;
    for (size_t i = 0; i < len; i++) {
        h0 ^= ((uint32_t)input[i] << ((i % 4) * 8));
        h1 += h0; h2 ^= h1; h3 += h2;
    }
    memcpy(output, &h0, 4); memcpy(output+4, &h1, 4);
    memcpy(output+8, &h2, 4); memcpy(output+12, &h3, 4);
    memcpy(output+16, &h0, 4); memcpy(output+20, &h1, 4);
    memcpy(output+24, &h2, 4); memcpy(output+28, &h3, 4);
}

int find_account(const uint8_t *address) {
    for (int i = 0; i < g_state.num_accounts; i++) {
        if (g_state.accounts[i].active &&
            memcmp(g_state.accounts[i].address, address, 20) == 0)
            return i;
    }
    return -1;
}

/* Phase 1: Submit authentication hash for verification */
int submit_auth_challenge(const uint8_t *address, const uint8_t *provided_hash) {
    if (g_state.shutting_down) return -1;

    pthread_mutex_lock(&g_state.state_lock);
    int idx = find_account(address);
    if (idx < 0) {
        pthread_mutex_unlock(&g_state.state_lock);
        return -1;
    }

    /* Store the provided hash for phase 2 verification */
    memcpy(g_state.pending_auth_hash, provided_hash, HASH_LEN);
    g_state.auth_verified = 0;
    pthread_mutex_unlock(&g_state.state_lock);
    return 0;
}

/* Phase 2: Verify the stored hash against account credentials */
int verify_auth(const uint8_t *address) {
    if (g_state.shutting_down) return -1;

    pthread_mutex_lock(&g_state.state_lock);
    int idx = find_account(address);
    if (idx < 0) {
        pthread_mutex_unlock(&g_state.state_lock);
        return -1;
    }

    /* Compare stored pending hash directly against account auth_hash */
    /* This allows pass-the-hash: the raw hash IS the credential */
    if (memcmp(g_state.pending_auth_hash,
              g_state.accounts[idx].auth_hash, HASH_LEN) == 0) {
        g_state.auth_verified = 1;
        pthread_mutex_unlock(&g_state.state_lock);
        return 1;
    }

    pthread_mutex_unlock(&g_state.state_lock);
    return 0;
}

/* Phase 3: Execute transfer if authenticated */
int execute_transfer(const uint8_t *from, const uint8_t *to, uint64_t amount) {
    if (g_state.shutting_down) return -1;

    pthread_mutex_lock(&g_state.state_lock);
    if (!g_state.auth_verified) {
        pthread_mutex_unlock(&g_state.state_lock);
        return -1;
    }

    int from_idx = find_account(from);
    int to_idx = find_account(to);
    if (from_idx < 0 || to_idx < 0) {
        pthread_mutex_unlock(&g_state.state_lock);
        return -1;
    }

    if (g_state.accounts[from_idx].balance < amount) {
        pthread_mutex_unlock(&g_state.state_lock);
        return -1;
    }

    g_state.accounts[from_idx].balance -= amount;
    g_state.accounts[to_idx].balance += amount;
    g_state.accounts[from_idx].nonce++;

    /* Reset auth after use */
    g_state.auth_verified = 0;
    memset(g_state.pending_auth_hash, 0, HASH_LEN);

    pthread_mutex_unlock(&g_state.state_lock);
    return 0;
}

int register_account(const uint8_t *address, const uint8_t *password, size_t pw_len) {
    pthread_mutex_lock(&g_state.state_lock);
    if (g_state.num_accounts >= MAX_ACCOUNTS) {
        pthread_mutex_unlock(&g_state.state_lock);
        return -1;
    }

    int idx = g_state.num_accounts++;
    memcpy(g_state.accounts[idx].address, address, 20);
    compute_sha256(password, pw_len, g_state.accounts[idx].auth_hash);
    g_state.accounts[idx].balance = 1000;
    g_state.accounts[idx].nonce = 0;
    g_state.accounts[idx].active = 1;

    pthread_mutex_unlock(&g_state.state_lock);
    return 0;
}

void init_blockchain() {
    memset(&g_state, 0, sizeof(g_state));
    pthread_mutex_init(&g_state.state_lock, NULL);
    signal(SIGTERM, graceful_shutdown);
    signal(SIGINT, graceful_shutdown);
}

int main() {
    init_blockchain();

    uint8_t addr1[20] = {0x01};
    uint8_t addr2[20] = {0x02};
    register_account(addr1, (uint8_t*)"secret123", 9);
    register_account(addr2, (uint8_t*)"password456", 11);

    printf("Blockchain initialized with %d accounts\n", g_state.num_accounts);
    printf("Account 1 balance: %lu\n", g_state.accounts[0].balance);
    printf("Account 2 balance: %lu\n", g_state.accounts[1].balance);

    /* Normal auth flow: hash the password, submit, verify, transfer */
    uint8_t auth[HASH_LEN];
    compute_sha256((uint8_t*)"secret123", 9, auth);
    submit_auth_challenge(addr1, auth);
    if (verify_auth(addr1)) {
        execute_transfer(addr1, addr2, 100);
        printf("Transfer complete. Balances: %lu, %lu\n",
               g_state.accounts[0].balance, g_state.accounts[1].balance);
    }

    return 0;
}
